def cache_sim(capacity, ttl, ops):
    cache = {}  # key -> (value, write_time)
    lru_order = []  # list of keys in LRU order (most recent at end)
    results = []

    def is_expired(key, current_time):
        if key not in cache:
            return True
        value, write_time = cache[key]
        return current_time >= write_time + ttl

    def remove_expired(current_time):
        expired_keys = [key for key in cache if is_expired(key, current_time)]
        for key in expired_keys:
            del cache[key]
            lru_order.remove(key)

    def mark_recently_used(key):
        if key in lru_order:
            lru_order.remove(key)
        lru_order.append(key)

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            remove_expired(t)

            if key in cache:
                # Key exists, update it
                cache[key] = (value, t)
                mark_recently_used(key)
            else:
                # Key doesn't exist
                if len(cache) >= capacity:
                    # Evict LRU
                    lru_key = lru_order.pop(0)
                    del cache[lru_key]

                cache[key] = (value, t)
                lru_order.append(key)

        elif op[0] == 'get':
            _, t, key = op
            remove_expired(t)

            if key in cache:
                value, write_time = cache[key]
                mark_recently_used(key)
                results.append(value)
            else:
                results.append(-1)

    return results

